<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { RouterLink } from 'vue-router';
import Breadcrumbs from '@/components/shared/Breadcrumbs.vue';
import ProductGrid from '@/components/catalog/ProductGrid.vue';
import TrustStrip from '@/components/catalog/TrustStrip.vue';
import { PRODUCTS, PRODUCT_BY_ID, productImageUrl, productImageCount, money, categoryUrl } from '@/utils/catalog.js';
import { useStorefront } from '@/composables/useStorefront.js';
import { SITE_NAME, SITE_EMAIL } from '@/config/siteInfo.js';
const props = defineProps({ slug: { type: String, default: '' }, pageInfo: { type: Object, default: () => ({}) } });
const { state, addToCart, toggleWishlist, openLightbox } = useStorefront();
const product = computed(() => PRODUCT_BY_ID.get(props.slug) || null);
const imageIndex = ref(0);
const quantity = ref(1);
const stickyVisible = ref(false);
const wished = computed(() => product.value ? Boolean(state.wishlist[product.value.id]) : false);
const related = computed(() => product.value ? PRODUCTS.filter(item => item.id !== product.value.id && (item.cat === product.value.cat || item.sub === product.value.sub)).slice(0, 4) : []);
const productUrl = computed(() => product.value ? productImageUrl(product.value, imageIndex.value, 1000) : '');
function updateScroll() { stickyVisible.value = window.scrollY > 620; }
function add(quantityToAdd = quantity.value) { if (product.value) addToCart(product.value.id, quantityToAdd); }
onMounted(() => window.addEventListener('scroll', updateScroll, { passive: true }));
onBeforeUnmount(() => window.removeEventListener('scroll', updateScroll));
</script>
<template>
  <main v-if="product">
    <section class="sec sec--tight"><div class="wrap"><Breadcrumbs :items="[{ label: 'Shop', to: '/shop/' }, { label: product.cat, to: categoryUrl(product.cat) }, { label: product.short }]" />
      <div class="pdp"><div class="pdp__gallery"><button class="pdp__main" type="button" aria-label="Enlarge product image" @click="openLightbox(product, imageIndex)"><img class="is-cutout" :src="productUrl" :alt="imageIndex ? `${product.name}, view ${imageIndex + 1}` : product.name" decoding="async"><span class="pdp__zoom"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.35-4.35M11 8v6M8 11h6"/></svg>Click to enlarge</span></button><div v-if="productImageCount(product) > 1" class="pdp__thumbs"><button v-for="(_, index) in product.amz" :key="`${product.id}-${index}`" class="pdp__thumb" :class="{ 'is-on': imageIndex === index }" :aria-label="`Show image ${index + 1}`" :aria-pressed="imageIndex === index" @click="imageIndex = index"><img class="is-cutout" :src="productImageUrl(product, index, 200)" :alt="`${product.name}, image ${index + 1}`" loading="lazy"></button></div></div>
        <div><p class="pdp__cat">{{ product.brand ? `${product.brand} · ` : '' }}{{ product.cat }} · {{ product.sub }}</p><h1>{{ product.name }}</h1><div class="pdp__price"><span class="price">{{ money(product.price) }}</span></div><div class="pdp__delivery"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg><span>In stock. Ships within 1 business day; standard delivery 3–6 business days.</span></div><ul class="bullets"><li v-for="bullet in product.bullets" :key="bullet">{{ bullet }}</li></ul><div class="buy"><div class="qty"><button aria-label="Decrease quantity" @click="quantity = Math.max(1, quantity - 1)">−</button><span>{{ quantity }}</span><button aria-label="Increase quantity" @click="quantity = Math.min(99, quantity + 1)">+</button></div><button class="btn btn--pri" @click="add()">Add to Cart · {{ money(product.price * quantity) }}</button><button class="pdp__wish" :class="{ 'is-on': wished }" :aria-pressed="wished" aria-label="Add to wishlist" @click="toggleWishlist(product.id)"><svg width="15" height="15" viewBox="0 0 24 24" :fill="wished ? 'currentColor' : 'none'" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>Save</button></div>
          <div class="pdp__meta"><div><strong>Brand</strong><span>{{ product.brand || SITE_NAME.replace(/ LLC$/, '') }}</span></div><div><strong>Item #</strong><span><code>{{ product.item }}</code></span></div><div><strong>Availability</strong><span>In stock — ships within 1 business day</span></div><div><strong>Shipping</strong><span>Free US shipping on orders over $50</span></div><div><strong>Returns</strong><span>30 days, unused, in original packaging</span></div></div>
        </div>
      </div>
    </div></section>
    <section class="sec sec--sand" id="details"><div class="wrap"><h2 class="detail-heading">Product details</h2><p class="prose-copy">Explore the product features and specifications below for more information before ordering.</p><h3 class="spec-heading">Specifications</h3><div class="spec-table"><table class="spec"><tbody><tr><th scope="row">Brand</th><td>{{ product.brand }}</td></tr><tr><th scope="row">Item #</th><td><code>{{ product.item }}</code></td></tr><tr v-for="([name, value]) in Object.entries(product.specs || {})" :key="name"><th scope="row">{{ name }}</th><td>{{ value }}</td></tr></tbody></table></div></div></section>
    <section class="sec" id="reviews"><div class="wrap"><div class="sec-head"><h2>Customer reviews</h2></div><div class="reviews"><div class="rev-summary"><div><p class="review-empty">No reviews yet</p><p class="review-text">Bought this product? Email <a :href="`mailto:${SITE_EMAIL}?subject=${encodeURIComponent(`Review: ${product.short}`)}`">{{ SITE_EMAIL }}</a> and tell us how it's working. We publish reviews from verified orders only.</p></div></div></div></div></section>
    <section v-if="related.length" class="sec sec--sand"><div class="wrap"><div class="sec-head"><h2>You may also need</h2></div><ProductGrid :products="related" /></div></section>
    <TrustStrip />
    <div v-if="stickyVisible" class="sticky-atc"><div class="sticky-atc__in"><div class="sticky-atc__art"><img class="is-cutout" :src="productImageUrl(product, 0, 120)" :alt="product.name"></div><div><div class="sticky-atc__name">{{ product.short }}</div><div class="sticky-atc__price">{{ money(product.price) }}</div></div><div class="sticky-atc__actions"><button class="btn btn--pri btn--sm" @click="add(1)">Add to Cart</button></div></div></div>
  </main>
  <main v-else><section class="sec"><div class="wrap center"><h1>Product not found</h1><p class="lede not-found-lede">The item you're looking for isn't in our catalog.</p><RouterLink to="/shop/" class="btn btn--pri">Back to Shop</RouterLink></div></section></main>
</template>
