gin:0}.review-text a{color:var(--clay);text-decoration:underline}.sticky-atc{position:fixed;bottom:0;left:0;right:0;background:rgba(251,250,247,.97);border-top:1px solid var(--line);backdrop-filter:blur(12px);z-index:50;animation:stickyUp .25s ease}.sticky-atc__in{max-width:var(--max);margin:auto;padding:.6rem 24px;display:flex;align-items:center;gap:.85rem}.sticky-atc__art{width:46px;height:46px;overflow:hidden;background:#fff;border-radius:var(--r-sm);flex-shrink:0}.sticky-atc__art img{width:100%;height:100%}.sticky-atc__name{font-size:.82rem;font-weight:600;max-width:50vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sticky-atc__price{font-family:var(--serif);font-weight:700;font-size:1rem}.sticky-atc__actions{margin-left:auto}@keyframes stickyUp{from{transform:translateY(100%)}to{transform:none}}.not-found-lede{margin:1rem auto 2rem}
